// Public API surface
pub mod internal;

// BUG: glob re-export — silently widens the public API to every pub item in internal::types,
// which today includes InternalLoan, RawSnapshot, LedgerCursor in addition to LoanResponse / LoanError.
pub use internal::types::*;

// Public contract per design: only LoanResponse and LoanError.
pub struct LoanResponse {
    pub id: uuid::Uuid,
    pub principal_cents: i64,
}

#[non_exhaustive]
pub enum LoanError {
    NotFound,
    Forbidden,
}

// These were intended pub(crate) per design but are pub here, then glob-re-exported above.
pub struct InternalLoan { pub raw: RawSnapshot }
pub struct RawSnapshot { pub bytes: Vec<u8> }
pub struct LedgerCursor { pub offset: u64 }
